def xero_bill_markdown(proposal, warnings=None, blocking=None, bill_id="", file_path="", client_name=""):
    """The review item's description: what the AI read, how it coded it, and what to check."""
    p = proposal or {}
    c = p.get("contact") or {}
    cur = p.get("currency") or ""
    sales = p.get("doc_type") == "ACCREC"
    raising = p.get("origin") == "request"
    doc = "invoice" if sales else "bill"
    out = []
    if raising:
        out.append("**Invoice to raise** from " + (client_name or "the client") + " to **" + (c.get("name") or "Unknown customer")
                   + "**" + (" (new customer)" if c.get("is_new") else "") + (" · " + c["email"] if c.get("email") else ""))
    elif sales:
        out.append("**Sales invoice** from " + (client_name or "the client") + " to **" + (c.get("name") or "Unknown customer")
                   + "**" + (" (new customer)" if c.get("is_new") else ""))
    else:
        out.append("**" + (c.get("name") or "Unknown supplier") + "**" + (" (new supplier)" if c.get("is_new") else "")
                   + (" for " + client_name if client_name else ""))
    out.append("")
    out.append("- Invoice " + (p.get("invoice_number") or ("numbered by Xero" if raising else "—")) + ", dated " + (p.get("date") or "—")
               + ", due " + (p.get("due_date") or "—"))
    out.append("- Total " + bk_fmt(p.get("total"), cur) + " (GST " + bk_fmt(p.get("tax"), cur) + ", amounts "
               + ("include" if p.get("line_amount_types") == "Inclusive" else "exclude") + " GST)")
    if bill_id:
        # Through the client's own organisation (its short code), or Xero opens whichever one the browser last used.
        out.append("- Draft " + doc + " in Xero: [open in Xero](" + xero_org_link(xero_bill_link(bill_id, p.get("doc_type") or "ACCPAY"),
                                                                    p.get("short_code")) + ")")
    else:
        out.append("- Not in Xero yet: the " + doc + " is created when you approve")
    if file_path:
        out.append("- PDF: `" + file_path + "` in Knowledge")
    out.append("")
    out.append("**Lines**")
    out.append("")
    # A list, not a table: WorkQ descriptions don't render markdown tables.
    for i, ln in enumerate(p.get("lines") or []):
        desc = str(ln.get("description") or "").replace("\n", " ")[:120]
        out.append("- Line " + str(i + 1) + ": " + desc + ", " + bk_fmt(ln.get("line_amount"), cur) + ". Account **"
                   + (ln.get("account_code") or "missing") + "**, tax " + (ln.get("tax_type") or "—") + ". "
                   + str(ln.get("reason") or "")[:160] + " (" + str(ln.get("confidence") or "low") + " confidence)")
    if blocking:
        out.append("")
        out.append("**Must fix before approving**")
        out.extend("- " + b for b in blocking)
    if warnings:
        out.append("")
        out.append("**Check**")
        out.extend("- " + w for w in warnings)
    out.append("")
    if raising:
        out.append("Fill in the **Invoice to send** form on this item: approve it (and choose whether Xero emails it to the "
                   "customer), change it, reject it or ask the client.")
    else:
        out.append("Fill in the **" + ("Invoice" if sales else "Bill") + " review** form on this item to approve, change, "
                   "reject or ask the client." + (" Approving records it in Xero as awaiting payment; nothing is emailed "
                                                  "to the customer." if sales else ""))
    return "\n".join(out)


def xero_org_link(link, short_code):
    """A Xero link that switches to the client's organisation first. A plain go.xero.com link opens in whichever
    organisation the browser last used, so for any other client it shows the wrong file or an error."""
    prefix = "https://go.xero.com"
    if not short_code or not str(link or "").startswith(prefix + "/"):
        return link
    return prefix + "/organisationlogin/default.aspx?shortcode=" + str(short_code) + "&redirecturl=" + link[len(prefix):]


# ── Send for review ──


problem = params.get("problem") or ""
ctx = params.get("ctx") or {}
settings = ctx.get("settings") or {}
client = ctx.get("client") or {}
proposal = params.get("proposal") or {}
warnings = params.get("warnings") or []
blocking = params.get("blocking") or []
bill_id = params.get("bill_id") or ""
path = params["path"]
folder = ctx.get("folder") or path.split("/")[1]
file_name = path.split("/")[-1]
today = bk_today(settings)
outcome = ""
todo_id = ""

if problem:
    dest = BK_FAILED + "/" + folder + "/" + file_name
    try:
        bk_move(path, dest)
    except Exception:
        dest = path
    owner = bk_exceptions_owner(settings, client)
    item = api.workq.create(
        title=("Bill needs attention: " + file_name + (" (" + client["name"] + ")" if client.get("name") else ""))[:200],
        scope="org",
        description=(problem + "\n\n- File: `" + dest + "` in Knowledge\n\n"
                     "When it's fixed, move the PDF back into `" + BK_INBOX + "/" + folder
                     + "`, or key the bill by hand and complete this item."),
        priority="high",
        due_date=str(bk_add_business_days(today, 1)),
        assignee_ids=[owner] if owner else None,
        labels=["bookkeeping", "bill-exception", folder],
    )
    todo_id = item["id"]
    outcome = "exception"
else:
    tenant = client["xero_tenant_id"]
    dest = BK_PROCESSED + "/" + client["slug"] + "/" + file_name
    bk_move(path, dest)
    total = proposal.get("total")
    auto_below = bk_money(settings.get("auto_approve_below")) or 0
    status = settings.get("approved_status") or "SUBMITTED"
    record = {
        "client_slug": client["slug"],
        "tenant_id": tenant,
        "bill_id": bill_id,
        "proposal": proposal,
        "warnings": warnings,
        "blocking": blocking,
        "confidence": params.get("confidence") or "low",
        "file": dest,
        "attach_error": params.get("attach_error") or "",
        "created_at": bk_now_iso(settings),
        "history": [],
    }
    sales = proposal.get("doc_type") == "ACCREC"
    # The checks catalogue IDs raised at intake, so the findings reports can count them.
    record["checks"] = sorted(set(re.findall(r"\[(CHK-\d{3})\]", " ".join(warnings))))
    # What later intake checks compare against: files seen (CHK-130), ABNs per supplier (CHK-090), and the sales
    # invoices captured here, which Ledger checks mustn't flag as "not sent" (CHK-024).
    seen = proposal.get("intake") or {}
    index_path = BK_CHECKS + "/" + client["slug"] + "-intake.json"
    index = bk_read_json(index_path) or {}
    files = index.get("files") or {}
    if seen.get("file_hash"):
        files[seen["file_hash"]] = {"date": str(today), "number": proposal.get("invoice_number") or ""}
    abns = index.get("abns") or {}
    if seen.get("abn") and seen.get("contact_key"):
        known = abns.get(seen["contact_key"]) or []
        abns[seen["contact_key"]] = (known + [seen["abn"]] if seen["abn"] not in known else known)[-5:]
    captured = index.get("captured") or []
    if sales and bill_id:
        captured = (captured + [bill_id])[-2000:]
    keep = sorted(files.items(), key=lambda kv: kv[1].get("date") or "")[-3000:]
    bk_write_json(index_path, {"files": dict(keep), "abns": abns, "captured": captured})
    can_skip = (bill_id and not sales and not blocking and not warnings and record["confidence"] == "high"
                and auto_below > 0 and total is not None and total < auto_below
                and not (proposal.get("contact") or {}).get("is_new"))
    if can_skip:
        xero_set_status(tenant, bill_id, status)
        record["status"] = "auto_approved"
        bk_write_json(BK_BILLS + "/auto-" + bill_id + ".json", record)
        outcome = "auto_approved"
    else:
        reviewer = bk_reviewer(settings, client)
        if record["attach_error"]:
            warnings = warnings + ["The PDF couldn't be attached to the Xero " + ("invoice" if sales else "bill") + ": "
                                   + record["attach_error"]]
        c = proposal.get("contact") or {}
        title = (("Review sales invoice: " if sales else "Review bill: ") + (c.get("name") or ("customer" if sales else "supplier")) + " " + (proposal.get("invoice_number") or "")
                 + " " + bk_fmt(total, proposal.get("currency") or "") + " (" + client.get("name", "") + ")")
        item = api.workq.create(
            title=re.sub(r"\s+", " ", title)[:200],
            scope="org",
            description=xero_bill_markdown(proposal, warnings, blocking, bill_id, dest, client.get("name", "")),
            priority="high" if (blocking or warnings or c.get("is_new")) else "medium",
            due_date=str(bk_add_business_days(today, 2)),
            assignee_ids=[reviewer] if reviewer else None,
            labels=["bookkeeping", "invoice-review" if sales else "bill-review", client["slug"]],
        )
        api.workq.attach_form(todo_id=item["id"], form_id=params["invoice_form"] if sales else params["review_form"])
        record["status"] = "in_review"
        record["review_todo_id"] = item["id"]
        bk_write_json(BK_BILLS + "/" + item["id"] + ".json", record)
        todo_id = item["id"]
        outcome = "review"
